function normalizarWebhook(cuerpo) {
  const salida = [];
  const entradas = (cuerpo && Array.isArray(cuerpo.entry)) ? cuerpo.entry : [];

  if (cuerpo && cuerpo.object === 'whatsapp_business_account') {
    for (const entrada of entradas) {
